# ---------------------------------------------------------------- patterns
def _luhn_ok(digits: str) -> bool:
    total, alt = 0, False
    for ch in reversed(digits):
        d = int(ch)
        if alt:
            d *= 2
            if d > 9:
                d -= 9
        total += d
        alt = not alt
    return total % 10 == 0


class SinRecognizer(PatternRecognizer):
    """Social Insurance Number: 9 digits that pass the Luhn check."""

    def __init__(self):
        super().__init__(
            supported_entity="CA_SIN",
            name="CaSinRecognizer",
            patterns=[Pattern("sin", r"\b\d{3}[ -]?\d{3}[ -]?\d{3}\b", 0.3)],
            context=["sin", "social insurance"],
        )

    def validate_result(self, pattern_text):
        digits = re.sub(r"\D", "", pattern_text)
        if len(digits) != 9:
            return False
        return True if _luhn_ok(digits) else None


