# ---------------------------------------------------------------- analyzer
def build_analyzer():
    ner = NerModelConfiguration(
        labels_to_ignore=[l for l in NerModelConfiguration().labels_to_ignore
                          if l != "ORG"]
    )
    nlp = SpacyNlpEngine(models=[{"lang_code": "en", "model_name": MODEL}],
                         ner_model_configuration=ner)
    engine = AnalyzerEngine(nlp_engine=nlp, supported_languages=["en"])
    for rec in (SinRecognizer(), CA_POSTAL, ON_HEALTH, ON_LICENCE,
                STREET_ADDRESS, WRITTEN_DATE):
        engine.registry.add_recognizer(rec)
    return engine


ANALYZER = build_analyzer()


NAME_TOKEN = re.compile(r"^[A-Z][a-z\u2019'\-]{2,}$")
NOT_A_NAME = {
    "Dear", "Best", "Thanks", "Department", "University", "Hospital",
    "Regards", "Sincerely", "Yours", "Health", "Canada", "Ontario",
    "Toronto", "Program", "Review", "Case", "Doctor", "Professor",
}


def _mark(start, end, entity_type):
    return type("R", (), {"start": start, "end": end,
                          "entity_type": entity_type, "score": 1.0})()


def _protected_spans(text, phrases):
    """Character ranges the user asked to keep."""
    spans = []
    for phrase in phrases:
        phrase = phrase.strip()
        if len(phrase) < 2:
            continue
        for m in re.finditer(re.escape(phrase), text, re.IGNORECASE):
            spans.append((m.start(), m.end()))
    return spans


def _expand_names(text, results):
    """A person caught once by full name is caught everywhere by first name."""
    tokens = set()
    for r in results:
        if r.entity_type not in ("PERSON", "LOOSE_NAME"):
            continue
        for tok in re.split(r"[\s,]+", text[r.start:r.end]):
            tok = tok.strip(".'\u2019-")
            if NAME_TOKEN.match(tok) and tok not in NOT_A_NAME:
                tokens.add(tok)
    extra = []
    for tok in tokens:
        for m in re.finditer(r"\b%s\b" % re.escape(tok), text):
            extra.append(_mark(m.start(), m.end(), "PERSON"))
    return extra


# Words that sit alone on a line in forms but are not somebody's name.
FORM_WORDS = {
    "first", "last", "name", "names", "middle", "initial", "patient",
    "telephone", "phone", "fax", "email", "address", "city", "province",
    "postal", "code", "date", "birth", "dob", "sex", "gender", "male",
    "female", "yes", "no", "page", "print", "form", "section", "notes",
    "note", "signature", "signed", "title", "position", "department",
    "hospital", "centre", "center", "clinic", "program", "programme",
    "drug", "dose", "height", "weight", "diagnosis", "treatment",
    "request", "requested", "approval", "approved", "denied", "review",
    "version", "total", "subtotal", "comments", "other", "none", "n/a",
    "true", "false", "optional", "required", "attached", "continued",
    "january", "february", "march", "april", "may", "june", "july",
    "august", "september", "october", "november", "december",
    "monday", "tuesday", "wednesday", "thursday", "friday", "saturday",
    "sunday", "ontario", "canada", "toronto",
}

LONE_NAME = re.compile(
    r"^[A-Z][A-Za-z\u2019'\-]{1,19}(?:[ ][A-Z][A-Za-z\u2019'\-]{1,19}){0,2}$")
LONE_NUMBER = re.compile(r"^\d{1,6}(?:[.,]\d{1,4})?$")


def _form_fields(text, want_names, want_numbers):
    """A form puts its answers alone on a line, with no sentence around them."""
    out, pos = [], 0
    for line in text.split("\n"):
        start = pos
        pos += len(line) + 1
        stripped = line.strip()
        if not stripped or len(stripped) > 40:
            continue
        offset = start + (len(line) - len(line.lstrip()))
        if want_numbers and LONE_NUMBER.match(stripped):
            out.append(_mark(offset, offset + len(stripped), "LOOSE_NUMBER"))
            continue
        if not want_names or not LONE_NAME.match(stripped):
            continue
        words = [w.lower().strip(".,") for w in stripped.split()]
        if any(w in FORM_WORDS for w in words):
            continue
        out.append(_mark(offset, offset + len(stripped), "LOOSE_NAME"))
    return out


def find_spans(text, wanted, extra_words, keep_words=(),
               loose_names=False, loose_numbers=False):
    """Return the non-overlapping character ranges that should be taken out."""
    found = []
    if wanted:
        found = list(ANALYZER.analyze(text=text, language="en",
                                      entities=wanted, score_threshold=0.4))
    if loose_names or loose_numbers:
        found += _form_fields(text, loose_names, loose_numbers)
    if "PERSON" in wanted or loose_names:
        found += _expand_names(text, found)

    # Anything the user asked to keep wins over anything found automatically.
    keep = _protected_spans(text, keep_words)
    if keep:
        found = [r for r in found
                 if not any(r.start < e and s < r.end for s, e in keep)]

    # Anything the user asked to remove is added no matter what.
    for word in extra_words:
        word = word.strip()
        if len(word) < 2:
            continue
        for m in re.finditer(re.escape(word), text, re.IGNORECASE):
            found.append(_mark(m.start(), m.end(), "EXTRA"))

    # Longest match wins where two findings overlap
    priority = {"EXTRA": 0, "PERSON": 1, "LOOSE_NAME": 1}
    found.sort(key=lambda r: (r.start, -(r.end - r.start),
                              priority.get(r.entity_type, 2)))
    kept, last_end = [], -1
    for r in found:
        if r.start >= last_end:
            kept.append(r)
            last_end = r.end
    return kept


def redact(text, wanted, extra_words, number_them, keep_words=(),
           loose_names=False, loose_numbers=False):
    """Return (redacted_text, {label: count})."""
    kept = find_spans(text, wanted, extra_words, keep_words,
                      loose_names, loose_numbers)
    counts, seen, out, cursor = {}, {}, [], 0
    for r in kept:
        label = LABELS.get(r.entity_type, r.entity_type)
        original = text[r.start:r.end]
        if number_them:
            key = (label, original.strip().lower())
            if key not in seen:
                seen[key] = sum(1 for k in seen if k[0] == label) + 1
            tag = "[%s %d]" % (label, seen[key])
        else:
            tag = "[%s]" % label
        out.append(text[cursor:r.start])
        out.append(tag)
        cursor = r.end
        counts[label] = counts.get(label, 0) + 1
    out.append(text[cursor:])
    return "".join(out), counts


# ------------------------------------------------------------ file reading
def _unshatter(text):
    """Some PDFs extract one word per line. Put those lines back together."""
    lines = text.split("\n")
    filled = [l for l in lines if l.strip()]
    if len(filled) < 12:
        return text
    lone = sum(1 for l in filled if len(l.split()) == 1)
    if lone / len(filled) < 0.6:
        return text

    out, buf = [], []
    for line in lines:
        stripped = line.strip()
        if not stripped:
            if buf:
                out.append(" ".join(buf)); buf = []
            out.append("")
        elif len(stripped.split()) == 1:
            buf.append(stripped)
        else:
            if buf:
                out.append(" ".join(buf)); buf = []
            out.append(stripped)
    if buf:
        out.append(" ".join(buf))
    return "\n".join(out)


def read_upload(storage):
    name = (storage.filename or "").lower()
    blob = storage.read()
    if len(blob) > MAX_BYTES:
        raise ValueError("That file is larger than 25 MB.")

    if name.endswith(".docx"):
        from docx import Document

        doc = Document(io.BytesIO(blob))
        parts = [p.text for p in doc.paragraphs]
        for table in doc.tables:
            for row in table.rows:
                parts.append("\t".join(c.text for c in row.cells))
        return "\n".join(parts)

    if name.endswith(".pdf"):
        from pypdf import PdfReader

        reader = PdfReader(io.BytesIO(blob))
        pages = []
        for page in reader.pages:
            # Layout mode keeps whole lines together. Without it some PDFs
            # come back one word per line, which wrecks the detection.
            try:
                out = page.extract_text(extraction_mode="layout") or ""
            except Exception:
                out = ""
            if not out.strip():
                out = page.extract_text() or ""
            pages.append(out)
        text = "\n\n".join(pages).strip()
        text = _unshatter(text)
        if not text:
            raise ValueError(
                "No text found in that PDF. It is probably a scan, which this "
                "tool cannot read."
            )
        return text

    if name.endswith((".txt", ".eml", ".md", ".csv")):
        return blob.decode("utf-8", errors="replace")

    if name.endswith(".doc"):
        raise ValueError("Old .doc files are not supported. Save as .docx first.")

    raise ValueError("Unsupported file type. Use .txt, .eml, .docx or .pdf.")


def redact_pdf_keep_layout(blob, wanted, extra_words, keep_words,
                           loose_names, loose_numbers, show_labels=False):
    """Black out words in the original PDF, leaving the layout alone.

    The text underneath is genuinely removed, not merely covered over.
    """
    import pymupdf

    doc = pymupdf.open(stream=blob, filetype="pdf")
    total = 0
    try:
        for page in doc:
            words = page.get_text("words")
            if not words:
                continue

            text, places, last = "", [], None
            for w in words:
                x0, y0, x1, y1 = w[0], w[1], w[2], w[3]
                token, block, line = w[4], w[5], w[6]
                if last is not None:
                    text += "\n" if (block, line) != last else " "
                last = (block, line)
                start = len(text)
                text += token
                places.append((start, len(text), pymupdf.Rect(x0, y0, x1, y1),
                               (block, line)))

            spans = find_spans(text, wanted, extra_words, keep_words,
                               loose_names, loose_numbers)
            if not spans:
                continue

            for span in spans:
                hits = [pl for pl in places
                        if pl[0] < span.end and span.start < pl[1]]
                if not hits:
                    continue
                total += 1
                label = LABELS.get(span.entity_type, span.entity_type)
                # One box per line, so a name split across a line break does
                # not black out everything in between.
                by_line = {}
                for pl in hits:
                    by_line[pl[3]] = (by_line[pl[3]] | pl[2]
                                      if pl[3] in by_line else pl[2])
                for i, box in enumerate(by_line.values()):
                    page.add_redact_annot(
                        box,
                        text=(" %s " % label) if (show_labels and i == 0) else None,
                        fill=(0, 0, 0),
                        text_color=(1, 1, 1),
                        fontsize=7,
                        align=pymupdf.TEXT_ALIGN_CENTER,
                    )
            page.apply_redactions(images=pymupdf.PDF_REDACT_IMAGE_NONE)

        doc.set_metadata({})
        out = io.BytesIO()
        doc.save(out, garbage=4, deflate=True, clean=True)
        return out.getvalue(), total
    finally:
        doc.close()


def make_pdf(text, mode="labels"):
    from reportlab.lib.pagesizes import letter
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import inch
    from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer

    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf, pagesize=letter,
        leftMargin=inch, rightMargin=inch,
        topMargin=inch, bottomMargin=inch,
        title="Redacted document", author="", subject="", creator="",
    )
    style = ParagraphStyle("body", fontName="Helvetica", fontSize=10.5,
                           leading=15)
    bar = ('<font color="black" backColor="black">'
           '&#9608;&#9608;&#9608;&#9608;&#9608;</font>')
    flow = []
    for line in text.split("\n"):
        safe = (line.replace("&", "&amp;").replace("<", "&lt;")
                    .replace(">", "&gt;"))
        if mode == "bars":
            safe = re.sub(r"\[[A-Z][A-Z ]*\d*\]", bar, safe)
        if safe.strip():
            flow.append(Paragraph(safe, style))
        else:
            flow.append(Spacer(1, 8))
    if not flow:
        flow = [Paragraph("(empty)", style)]
    doc.build(flow)
    return buf.getvalue()


# ------------------------------------------------------------------ routes
def no_store(resp):
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Referrer-Policy"] = "no-referrer"
    resp.headers["X-Robots-Tag"] = "noindex, nofollow, noarchive, nosnippet"
    resp.headers["X-Content-Type-Options"] = "nosniff"
    return resp


@app.after_request
def _headers(resp):
    return no_store(resp)


def wanted_entities(form):
    wanted = []
    if form.get("names") == "on":
        wanted += GROUP_NAMES
    if form.get("contact") == "on":
        wanted += GROUP_CONTACT
    if form.get("address") == "on":
        wanted += GROUP_ADDRESS
    if form.get("places") == "on":
        wanted += GROUP_PLACE
    if form.get("orgs") == "on":
        wanted += GROUP_ORG
    if form.get("ids") == "on":
        wanted += GROUP_IDS
    if form.get("dates") == "on":
        wanted += GROUP_DATES
    return wanted


@app.route("/redact", methods=["POST"])
def do_redact():
    try:
        upload = request.files.get("file")
        if upload and upload.filename:
            text = read_upload(upload)
        else:
            text = request.form.get("text", "")
        if not text.strip():
            return jsonify({"error": "Nothing to redact."}), 400

        extra = [w for w in re.split(r"[,\n]", request.form.get("extra", "")) if w.strip()]
        keep = [w for w in re.split(r"[,\n]", request.form.get("keep", ""))
                if w.strip()]
        result, counts = redact(
            text,
            wanted_entities(request.form),
            extra,
            request.form.get("number") == "on",
            keep,
            request.form.get("loosenames") == "on",
            request.form.get("loosenumbers") == "on",
        )
        summary = ", ".join("%s: %d" % (k.lower(), v)
                           for k, v in sorted(counts.items()))
        return jsonify({"text": result,
                        "count": sum(counts.values()),
                        "summary": summary or "nothing found"})
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400
    except Exception:
        return jsonify({"error": "That file could not be read."}), 400


@app.route("/pdf", methods=["POST"])
def do_pdf():
    text = request.form.get("text", "")
    if not text.strip():
        return jsonify({"error": "Nothing to save."}), 400
    data = make_pdf(text, request.form.get("mode", "labels"))
    resp = Response(data, mimetype="application/pdf")
    resp.headers["Content-Disposition"] = 'attachment; filename="redacted.pdf"'
    return resp


